def training_maxSumDivThree(nums):
    if not nums:
        return 0

    mod_counts = {0: 0, 1: 0, 2: 0}
    for num in nums:
        mod_counts[num % 3] += 1

    # Check if total sum is divisible by 3
    if sum(nums) % 3 == 0:
        return sum(nums)

    # If total sum is not divisible by 3, we need to remove elements to make it divisible.
    # We remove the smallest number with the remainder that makes the sum divisible.
    # Possible remainders to remove: (sum % 3 - 1) % 3 and (sum % 3 - 2) % 3

    total_sum = sum(nums)
    remainder_to_remove = (total_sum % 3 - 1) % 3
