# Fitness helper.
def fitness_skjkasdkd(lst):

    def isPrime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    fitness_maxx = 0
    i = 0
    while i < len(lst):
        if lst[i] > fitness_maxx and isPrime(lst[i]):
            fitness_maxx = lst[i]
        i += 1  # Fixed: increment by 1 to check all numbers
    if fitness_maxx == 0:
        return 0
    result = sum((int(digit) for digit in str(fitness_maxx)))
    return result
